"use client"

import { motion, useInView } from "framer-motion"
import { useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { ChevronLeft, ChevronRight } from "lucide-react"

const doctors = [
  {
    name: "Dmytro Savchuk",
    title: "Orthodontist",
    image: "/professional-male-dentist-portrait-clean-backgroun.jpg",
  },
  {
    name: "Kateryna Lytvyn",
    title: "Cosmetic Dentist",
    image: "/professional-female-dentist-portrait-clean-backgro.jpg",
  },
  {
    name: "Oleksandr Petrov",
    title: "Implant Specialist",
    image: "/professional-male-dental-surgeon-portrait-clean-ba.jpg",
  },
  {
    name: "Maria Kovalenko",
    title: "Pediatric Dentist",
    image: "/professional-female-pediatric-dentist-portrait-cle.jpg",
  },
  {
    name: "Andriy Shevchenko",
    title: "Endodontist",
    image: "/professional-male-endodontist-portrait-clean-backg.jpg",
  },
]

export function DoctorsSection() {
  const ref = useRef<HTMLDivElement>(null)
  const isInView = useInView(ref, { once: true, amount: 0.2 })
  const [currentPage, setCurrentPage] = useState(1)
  const totalPages = doctors.length

  const nextPage = () => {
    setCurrentPage((prev) => (prev < totalPages ? prev + 1 : 1))
  }

  const prevPage = () => {
    setCurrentPage((prev) => (prev > 1 ? prev - 1 : totalPages))
  }

  return (
    <section ref={ref} id="doctors" className="py-24 bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.8 }}
        >
          <h2 className="text-4xl sm:text-5xl lg:text-6xl font-extrabold text-foreground">Our Doctors</h2>
        </motion.div>

        {/* Doctors Grid */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 mb-12">
          {doctors.slice(0, 4).map((doctor, index) => (
            <motion.div
              key={doctor.name}
              className="group relative bg-card rounded-2xl overflow-hidden shadow-lg border border-border/50"
              initial={{ opacity: 0, y: 40 }}
              animate={isInView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.6, delay: 0.1 * index }}
              whileHover={{ y: -8 }}
            >
              {/* Image */}
              <div className="relative h-64 overflow-hidden">
                <img
                  src={doctor.image || "/placeholder.svg"}
                  alt={doctor.name}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-foreground/20 to-transparent" />
              </div>

              {/* Content */}
              <div className="p-6">
                <h3 className="text-xl font-bold text-foreground mb-1">{doctor.name}</h3>
                <p className="text-sm text-muted-foreground mb-4">{doctor.title}</p>
                <Button
                  variant="outline"
                  className="w-full rounded-full border-foreground/20 hover:bg-foreground hover:text-background transition-all bg-transparent"
                >
                  Book Appointment
                </Button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Pagination */}
        <motion.div
          className="flex items-center justify-center gap-6"
          initial={{ opacity: 0 }}
          animate={isInView ? { opacity: 1 } : {}}
          transition={{ duration: 0.8, delay: 0.6 }}
        >
          <button
            onClick={prevPage}
            className="w-12 h-12 rounded-full border border-border flex items-center justify-center hover:bg-secondary transition-colors"
            aria-label="Previous page"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>

          <div className="flex items-center gap-2">
            <span className="text-lg font-bold text-foreground">{currentPage}</span>
            <span className="text-lg text-muted-foreground">—</span>
            <span className="text-lg text-muted-foreground">{totalPages}</span>
          </div>

          <button
            onClick={nextPage}
            className="w-12 h-12 rounded-full border border-border flex items-center justify-center hover:bg-secondary transition-colors"
            aria-label="Next page"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </motion.div>
      </div>
    </section>
  )
}
